-- 090: Six Flags AstroWorld (Houston), a new park, closed 30 Oct 2005, with the
-- twelve coasters Carter sent from RCDB, 2026-10-31. Every one is removed;
-- most closed with the park on 30 Oct 2005.
--   Batman The Escape: Intamin Stand-Up, 90 ft, 2,300 ft, 1 inv, 1993–2005.
--   Excalibur: Arrow Mine Train, 88 ft, 46 mph, 2,637 ft, 2:51, 1972–1998 (then
--     Frontier City).
--   Greezed Lightnin': Schwarzkopf Shuttle Loop (flywheel), 137.8 ft, 60 mph,
--     849 ft, 0:33, 1978–2005.
--   Mayan Mindbender: Vekoma custom MK-700, enclosed (-> "Indoor", as the site
--     files its other indoor Vekomas), 27.9 ft, 1,148.3 ft, 1995–2005.
--   Serial Thriller: Vekoma SLC (689m), 109.3 ft, 49.7 mph, 2,260.5 ft, 5 inv,
--     1:36, 29 May 1999–2005.
--   Serpent: Arrow Mini Mine Train, 14 mph, 810 ft, 1:29, 1969–2005.
--   Swamp Buggy: Chance toboggan, 45 ft, 450 ft, 1970–1972 (RCDB: "≥ 1972").
--   Texas Cyclone: wood, Frontier Construction Company (a Coney Island Cyclone
--     mirror), 93 ft, 3,180 ft, 2:15, 12 Jun 1976–2005.
--   Texas Tornado: Schwarzkopf custom 4-loop (the Thriller of Gröna Lund, 089),
--     115 ft, 54 mph, 3,675 ft, 14 Mar 1998–11 Mar 2001.
--   Ultra Twister: TOGO Ultra Twister, 96.8 ft, 44 mph, 1,421 ft, 3 inv, 1:40,
--     1990–2005.
--   Viper: Schwarzkopf Looping Star, 80.4 ft, 47.8 mph, 1,942.3 ft, 1 inv,
--     1989–2005.
--   XLR-8: Arrow Suspended, 81 ft, 34.1 mph, 3,000 ft, 3:00, 12 May 1984–2005.
-- Park pinned at the old site south of the Astrodome. Every insert checks the
-- row is not already there, so a second run is a no-op; each new coaster gets
-- its coaster_added row for /changes.
INSERT INTO parks (name, lat, lon, region) SELECT 'Six Flags AstroWorld', 29.6745, -95.4072, 'Texas, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Six Flags AstroWorld');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Batman The Escape', 'Six Flags AstroWorld', 'Steel', 'Intamin', 'Intamin Stand-Up', 90.0, NULL, 2300.0, 1, NULL, 1993, '1993', 'year', '2005-10-30', 'day', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Batman The Escape' AND park = 'Six Flags AstroWorld');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Batman The Escape' AND c.park = 'Six Flags AstroWorld' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Excalibur', 'Six Flags AstroWorld', 'Steel', 'Arrow Dynamics', 'Mine Train', 88.0, 46.0, 2637.0, 0, 171, 1972, '1972', 'year', '1998', 'year', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Excalibur' AND park = 'Six Flags AstroWorld');
